#include <stdio.h>

struct Item {
    int id;
    int qty;
    int price;
};

int total(struct Item *p, int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += (p + i)->qty * (p + i)->price;
    }
    return sum;
}

void swap(struct Item *a, struct Item *b) {
    struct Item t = *a;
    *a = *b;
    *b = t;
}

int main() {
    struct Item arr[4] = { {1, 3, 200}, {2, 5, 100}, {3, 2, 450}, {4, 4, 150} };
    struct Item *p = arr;
    int idx = 0;
    for (int i = 1; i < 4; i++) {
        if ((p + i)->qty * (p + i)->price > (p + idx)->qty * (p + idx)->price)
            idx = i;
    }
    swap(&arr[0], &arr[idx]);
    p++;
    p->qty += 2;
    printf("%d %d\n", arr[0].id, arr[1].qty);
    printf("%d\n", total(arr, 4));
    return 0;
}

#include <stdio.h>

void rotate(int m[][3]) {
    int i, j, t;
    for (i = 0; i < 3; i++) {
        for (j = i + 1; j < 3; j++) {
            t = m[i][j];
            m[i][j] = m[j][i];
            m[j][i] = t;
        }
    }
    for (i = 0; i < 3; i++) {
        t = m[i][0];
        m[i][0] = m[i][2];
        m[i][2] = t;
    }
}

int main() {
    int m[3][3] = { {3, 1, 4}, {1, 5, 9}, {2, 6, 5} };
    int i, d1 = 0, d2 = 0;
    rotate(m);
    for (i = 0; i < 3; i++) {
        d1 += m[i][i];
        d2 += m[i][2 - i];
    }
    printf("%d", m[1][0]);
    for (i = 1; i < 3; i++)
        printf(" %d", m[1][i]);
    printf("\n");
    printf("%d %d\n", d1, d2);
    return 0;
}

#include <stdio.h>

int len(char *s) {
    int n = 0;
    while (*s++)
        n++;
    return n;
}

void reverse(char *s) {
    int i = 0, j = len(s) - 1;
    while (i < j) {
        char t = s[i];
        s[i] = s[j];
        s[j] = t;
        i++;
        j--;
    }
}

int main() {
    char str[] = "Abc12xY3";
    int sum = 0, up = 0, i;
    for (i = 0; str[i] != '\0'; i++) {
        if (str[i] >= '0' && str[i] <= '9') {
            sum += str[i] - '0';
            str[i] = '*';
        } else if (str[i] >= 'a' && str[i] <= 'z') {
            str[i] = str[i] - 'a' + 'A';
            up++;
        } else if (str[i] >= 'A' && str[i] <= 'Z') {
            str[i] = str[i] + ('a' - 'A');
        }
    }
    reverse(str);
    printf("%s\n", str);
    printf("%d %d %d\n", sum, up, len(str));
    return 0;
}

