int main() {
    int i = 0, a = 0, b = 0, c = 0;
    do {
        i++;
        if (i % 4 == 0)
            continue;
        switch (i % 3) {
            case 0:
                a += i;
            case 1:
                b += i;
                break;
            case 2:
                c += i;
                if (c > 5)
                    break;
                a++;
        }
        if (a + b + c > 40)
            break;
    } while (i < 10);
    printf("%d %d %d\n", a, b, c);
    printf("%d\n", i);
    return 0;
}

#include <stdio.h>

int add(int a, int b) { return a + b; }
int mul(int a, int b) { return a * b; }
int sub(int a, int b) { return a - b; }

int apply(int (*f)(int, int), int x, int y) {
    return f(x, y);
}

int main() {
    int (*ops[3])(int, int) = { add, mul, sub };
    int data[6] = { 2, 5, 1, 4, 3, 7 };
    int cnt[3] = { 0, 0, 0 };
    int r = 1, i;
    for (i = 0; i < 6; i++) {
        int k = data[i] % 3;
        r = apply(ops[k], r, data[i]);
        cnt[k]++;
    }
    printf("%d\n", r);
    printf("%d %d %d\n", cnt[0], cnt[1], cnt[2]);
    return 0;
}

#include <stdio.h>

#define N 2 + 3
#define SQUARE(x) x * x
#define HALF(x) x / 2
#define CUBE(x) ((x) * (x) * (x))

int main() {
    int a = 4, b = 9;
    int r1 = N * N;
    int r2 = SQUARE(a + 1);
    int r3 = 36 / HALF(b - 3);
    int r4 = CUBE(a - 1) - SQUARE(a) / 2;
    int x = 5;
    int y = x++ * 2;
    y += ++x - N;
    printf("%d %d %d %d\n", r1, r2, r3, r4);
    printf("%d %d\n", x, y);
    return 0;
}
